{"status": 0, "output": """"Deployed v2 application. Run python3 project/portal.py serve [port].

`migrate` imports the recurring series listed in input/intake.json.  Each entry
cites a signed approval in input/records/<order>.txt; the approval decides
whether the series keeps the venue-local clock time or the UTC clock time of
its first occurrence.  Migration is incremental and repeatable: series rows are
upserted, the first occurrence is merged into `events` without overwriting an
existing UID, and bookings are never touched.
"""
import argparse
from datetime import date, datetime, time, timedelta, timezone
from html import escape
from http.server import BaseHTTPRequestHandler, HTTPServer
import json
import os
import sqlite3
from urllib.parse import parse_qs, urlsplit
from zoneinfo import ZoneInfo

RECORDS = os.path.join("input", "records")
INTAKE = os.path.join("input", "intake.json")

SERIES_SCHEMA = """
CREATE TABLE IF NOT EXISTS series(
    code TEXT PRIMARY KEY,
    zone TEXT NOT NULL,
    rule TEXT NOT NULL,          -- local_clock | utc_clock
    anchor_utc TEXT NOT NULL,
    weekday INTEGER NOT NULL,    -- Monday=0 .. Sunday=6
    local_time TEXT,             -- HH:MM for local_clock
    utc_time TEXT,               -- HH:MM for utc_clock
    order_id TEXT NOT NULL,
    channels TEXT NOT NULL DEFAULT 'A,B'
)
"""


def parse_utc(text):
    return datetime.fromisoformat(text.replace("Z", "+00:00"))


def fmt_utc(stamp):
    return stamp.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def is_iso_date(text):
    try:
        date.fromisoformat(text)
    except (TypeError, ValueError):
        return False
    return True


def stored_events(db, start, end):
    rows = db.execute("select uid, starts from events order by uid")
    return [dict(uid=u, utc=s, status="CONFIRMED") for u,s in rows if start <= s[:10] <= end]


def series_rows(db):
    try:
        cur = db.execute("select code,zone,rule,anchor_utc,weekday,local_time,utc_time,order_id,channels from series")
    except sqlite3.OperationalError:
        return []
    cols = ("code","zone","rule","anchor_utc","weekday","local_time","utc_time","order_id","channels")
    return [dict(zip(cols, row)) for row in cur]


def series_channels(series):
    """Channels this series is published to; absent/blank means both."""
    raw = series.get("channels") or "A,B"
    return {part.strip() for part in str(raw).split(",") if part.strip()}


def normalize_channels(value):
    if value is None:
        return None
    if isinstance(value, str):
        parts = value.split(",")
    else:
        parts = list(value)
    channels = sorted({str(part).strip().upper() for part in parts if str(part).strip()})
    unknown = set(channels) - {"A","B"}
    if not channels or unknown:
        raise ValueError(f"invalid channel scope: {value!r}")
    return ",".join(channels)


def occurrences(series, start, end):
    """Expand one series over the inclusive service-day range [start, end]."""
    zone = ZoneInfo(series["zone"])
    day = date.fromisoformat(start) - timedelta(days=1)
    last = date.fromisoformat(end) + timedelta(days=1)
    rows = []
    while day <= last:
        if day.weekday() == series["weekday"]:
            if series["rule"] == "local_clock":
                local = datetime.combine(day, time.fromisoformat(series["local_time"]), tzinfo=zone)
                stamp = local.astimezone(timezone.utc)
                service = local.date()
            else:
                stamp = datetime.combine(day, time.fromisoformat(series["utc_time"]), tzinfo=timezone.utc)
                service = stamp.date()
            if start <= service.isoformat() <= end:
                rows.append(dict(uid=series["code"] + "-" + service.strftime("%Y%m%d"),
                                 utc=fmt_utc(stamp), status="CONFIRMED"))
        day += timedelta(days=1)
    return rows


def expanded_events(db, start, end, channel=None):
    """Stored events plus series occurrences; a stored UID always wins."""
    rows = stored_events(db, start, end)
    seen = {row["uid"] for row in rows}
    for series in series_rows(db):
        if channel is not None and channel not in series_channels(series):
            continue
        for row in occurrences(series, start, end):
            if row["uid"] not in seen:
                seen.add(row["uid"])
                rows.append(row)
