def parse_change_approval(text, source, year):
    """Parse a signed change approval into structured per-occurrence overrides.

    Supported grammar (one paragraph per approval):
      <CODE> 原定 M月D日[、D日]... [场次] (提前|推迟)N(日|天|小时|时)
