    days = [int(date_match.group(2))]
    days.extend(int(part) for part in re.findall(r"(\\d{1,2})\\s*日", date_match.group(3)))
    shift_match = re.search(r"(提前|推迟)\\s*([0-9一二两三四五六七八九十]+)\\s*(日|天|小时|时)", text)
